export function selectMobileRenderBudget({active=!1,width=1280,screenWidth=width,screenHeight=800,coarse=!1}={}){const mobile=active&&(width<=760||coarse&&Math.min(screenWidth,screenHeight)<=900);return Object.freeze({mobile,dpr:mobile?1.25:1.65,sceneSamples:mobile?0:4,reflectionSize:mobile?512:1024})}